"""Individual close readings. Coverage labels distinguish books from selections."""
ART_NOTE = {
 'troika':'У Перова тяжесть жизни становится видимой через позы детей и сопротивление дороги. Сопоставьте эту зрительную подробность с одной деталью литературного текста. Это самостоятельная картина, не иллюстрация к выбранной книге.',
 'rooks':'У Саврасова обновление природы раскрывается через конкретное место и неброские детали. Найдите в тексте столь же точное наблюдение. Совпадение темы не означает совпадения сюжета.',
 'philosophers':'В картине Нестерова два человека идут рядом, сохраняя различие облика и выражения лиц. Подумайте, как автор книги показывает встречу разных взглядов. Изображённые философы не являются персонажами разбираемого произведения.',
 'prodigal':'У Рембрандта возвращение выражено прикосновением и расположением фигур. Сопоставьте это с отношением к ошибившемуся в книге. Евангельский сюжет картины сохраняет самостоятельный смысл.',
 'bilibin':'Рассмотрите, как Билибин организует сказочное пространство: границу света и тьмы, фигуру героя, орнамент. Выберите сходный по функции приём в словесном тексте. На иллюстрации изображена Василиса, а не герой этой книги.',
 'levitan':'Левитан соединяет видимый пейзаж с предполагаемым звучанием колоколов. Как книга связывает внешнее наблюдение и внутренний отклик? Картина не служит документом описанных событий.',
 'bartholomew':'Нестеров изображает встречу отрока Варфоломея со старцем. Сопоставьте жест слушания с одной сценой книги; не отождествляйте литературного героя с персонажем жития.',
 'ninth-wave':'Айвазовский показывает человеческую уязвимость перед морем и усилие удержаться вместе. Какие средства текста создают сходное чувство? Это тематическое сопоставление, а не иллюстрация конкретного эпизода.',
}

def make(key, title, author, scope, paragraphs, quote, reflection, task, sources, art='philosophers', music='cello'):
    return dict(slug=key, title=title, author=author, textbook=key, scope=scope,
                paragraphs=paragraphs, quote=quote, reflection='Комментарий мастерской: '+reflection,
                task=task, sources=sources, source=sources[0][0], source_label=sources[0][1],
                art=art, music=music, art_note=ART_NOTE[art],
                music_note=('Прослушайте знаменный распев, обращая внимание на связь напева и слова. Затем вернитесь к интонации рассказчика. Молитвенное пение не является саундтреком книги.' if music=='chant' else 'В прелюдии виолончельной сюиты Баха проследите повтор и изменение движения. Найдите в книге повтор, который тоже получает новое значение. Это сравнение художественных приёмов, а не приписывание музыке литературного сюжета.'))

